string longestCommonPrefix(const vector<string>& strs) {
    if (strs.empty()) return "";
    for (size_t col = 0; col < strs[0].size(); ++col) {
        char c = strs[0][col];
        for (size_t w = 1; w < strs.size(); ++w)
            if (col >= strs[w].size() || strs[w][col] != c)
                return strs[0].substr(0, col);     // first mismatch or short word
    }
    return strs[0];                                 // first word is the whole prefix
}

