int myAtoi(const string& s) {
    size_t i = 0;
    // STAGE 1: leading whitespace only
    while (i < s.size() && s[i] == ' ') ++i;
    // STAGE 2: at most ONE sign
    int sign = 1;
    if (i < s.size() && (s[i] == '+' || s[i] == '-')) sign = (s[i++] == '-') ? -1 : 1;
    // STAGE 3: digits, checking overflow BEFORE it happens
    long long result = 0;
    while (i < s.size() && isdigit((unsigned char)s[i])) {
        int d = s[i++] - '0';
        result = result * 10 + d;
        if (sign == 1 && result > INT_MAX)  return INT_MAX;   // clamp, do not wrap
        if (sign == -1 && -result < INT_MIN) return INT_MIN;
    }
    return (int)(sign * result);
}

bool isIsomorphic(const string& s, const string& t) {
    if (s.size() != t.size()) return false;
    int forward[128] = {0}, backward[128] = {0};   // 0 means "unmapped"
    for (size_t i = 0; i < s.size(); ++i) {
        unsigned char a = s[i], b = t[i];
        if (forward[a] == 0 && backward[b] == 0) { forward[a] = b; backward[b] = a; }
        else if (forward[a] != b || backward[b] != a) return false;   // conflict
    }
    return true;
}

