def is_isomorphic(s: str, t: str) -> bool:
    if len(s) != len(t):
        return False
    forward, backward = {}, {}
    for a, b in zip(s, t):
        if a not in forward and b not in backward:
            forward[a], backward[b] = b, a
        elif forward.get(a) != b or backward.get(b) != a:
            return False        # conflict in either direction
    return True

