int compress(vector<char>& chars) {
    int write = 0, read = 0, n = (int)chars.size();
    while (read < n) {
        char c = chars[read];
        int runStart = read;
        while (read < n && chars[read] == c) ++read;   // measure the run
        chars[write++] = c;
        int count = read - runStart;
        if (count > 1) {                               // 1 is written as nothing
            string digits = to_string(count);
            for (char d : digits) chars[write++] = d;  // 12 becomes '1','2'
        }
    }
    return write;
}

string zigzagConvert(const string& s, int numRows) {
    if (numRows == 1) return s;               // no bounce: infinite loop trap
    vector<string> rows(min((size_t)numRows, s.size()));
    int row = 0, step = 1;
    for (char c : s) {
        rows[row] += c;
        if (row == 0)                 step = 1;    // hit the top rail
        else if (row == numRows - 1)  step = -1;   // hit the bottom rail
        row += step;
    }
    string out;
    for (const string& r : rows) out += r;
    return out;
}

