def zigzag_convert(s: str, num_rows: int) -> str:
    if num_rows == 1:
        return s                       # no bounce: infinite loop trap
    rows = [[] for _ in range(min(num_rows, len(s)))]
    row, step = 0, 1
    for c in s:
        rows[row].append(c)
        if row == 0:
            step = 1                   # hit the top rail
        elif row == num_rows - 1:
            step = -1                  # hit the bottom rail
        row += step
    return "".join("".join(r) for r in rows)

