string longestPalindrome(const string& s) {
    if (s.empty()) return "";
    int bestLo = 0, bestLen = 1;
    auto expand = [&](int l, int r) {
        while (l >= 0 && r < (int)s.size() && s[l] == s[r]) { --l; ++r; }
        int len = r - l - 1;                  // l and r have overshot by one
        if (len > bestLen) { bestLen = len; bestLo = l + 1; }
    };
    for (int i = 0; i < (int)s.size(); ++i) {
        expand(i, i);        // odd length, centred on a character
        expand(i, i + 1);    // even length, centred between characters
    }
    return s.substr(bestLo, bestLen);
}

