def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    best_lo, best_len = 0, 1

    def expand(l: int, r: int) -> None:
        nonlocal best_lo, best_len
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        length = r - l - 1          # l and r have overshot by one
        if length > best_len:
            best_len, best_lo = length, l + 1

    for i in range(len(s)):
        expand(i, i)                # odd length, centred on a character
        expand(i, i + 1)            # even length, centred between characters
    return s[best_lo:best_lo + best_len]

