string intToRoman(int num) {
    // The subtractive forms are TABLE ENTRIES, not special cases.
    static const vector<pair<int,string>> table = {
        {1000,"M"},{900,"CM"},{500,"D"},{400,"CD"},{100,"C"},{90,"XC"},
        {50,"L"},{40,"XL"},{10,"X"},{9,"IX"},{5,"V"},{4,"IV"},{1,"I"}
    };
    string out;
    for (auto& [val, sym] : table)
        while (num >= val) { out += sym; num -= val; }   // greedy: largest first
    return out;
}

int romanToInt(const string& s) {
    unordered_map<char,int> v{{'I',1},{'V',5},{'X',10},{'L',50},
                              {'C',100},{'D',500},{'M',1000}};
    int total = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        // a smaller symbol before a larger one is subtractive
        if (i + 1 < s.size() && v[s[i]] < v[s[i + 1]]) total -= v[s[i]];
        else                                           total += v[s[i]];
    }
    return total;
}

